import{_ as a,o as t,c as i,a0 as s}from"./chunks/framework.CzVS_xMp.js";const f=JSON.parse('{"title":"Lab: NIXL-Style Tier Handoff","description":"","frontmatter":{},"headers":[],"relativePath":"systems-performance/labs/ch04/nixl-tier-handoff/index.md","filePath":"systems-performance/labs/ch04/nixl-tier-handoff/index.md","lastUpdated":1788490169000}'),n={name:"systems-performance/labs/ch04/nixl-tier-handoff/index.md"};function o(r,e,l,h,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="lab-nixl-style-tier-handoff" tabindex="-1">Lab: NIXL-Style Tier Handoff <a class="header-anchor" href="#lab-nixl-style-tier-handoff" aria-label="Permalink to &quot;Lab: NIXL-Style Tier Handoff&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Show why Chapter 4 separates training collectives from disaggregated inference data movement. NCCL is the right lens for all-reduce, but KV cache handoff is a point-to-point transfer problem.</p><p>This lab adapts the important idea behind baseline and optimized NIXL-style tier handoff examples.</p><h2 id="baseline" tabindex="-1">Baseline <a class="header-anchor" href="#baseline" aria-label="Permalink to &quot;Baseline&quot;">​</a></h2><p>The baseline copies selected KV blocks one at a time through a CPU staging buffer. Each block pays fixed scheduling overhead and creates fragmented movement.</p><h2 id="optimized" tabindex="-1">Optimized <a class="header-anchor" href="#optimized" aria-label="Permalink to &quot;Optimized&quot;">​</a></h2><p>The optimized path packs selected blocks into one contiguous transfer and unpacks at the target tier. This models a NIXL/UCX-style handoff where the movement layer sees a compact payload.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare.py</span></span></code></pre></div><h2 id="expected-observation" tabindex="-1">Expected Observation <a class="header-anchor" href="#expected-observation" aria-label="Permalink to &quot;Expected Observation&quot;">​</a></h2><p>The optimized path should transfer the same selected KV bytes with fewer operations and lower elapsed time.</p><h2 id="what-this-proves" tabindex="-1">What This Proves <a class="header-anchor" href="#what-this-proves" aria-label="Permalink to &quot;What This Proves&quot;">​</a></h2><p>Disaggregated serving performance depends on the shape of KV movement: block selection, packing, registration reuse, and prefill/decode placement matter as much as raw link bandwidth.</p>',14)])])}const m=a(n,[["render",o]]);export{f as __pageData,m as default};
